<template><view class="chat-page" :class="{'chat-page--embedded':embedded}">
  <view class="chat-toolbar"><button @tap="back">‹ 对话</button><view><text class="chat-title">{{ conversationTitle(conversation) }}</text><text class="chat-subtitle">{{ conversation?.type==='group'?conversation.members.length+' 位群成员':'一对一私聊' }}{{ conversation?.schoolGroup?' · '+schoolLabel(conversation.schoolGroup):'' }}</text></view><button v-if="conversation?.type==='group'" @tap="toggleMembers">成员</button></view>
  <view v-if="error" class="chat-error" role="alert">{{ error }}<text @tap="refresh(true)">重试</text></view>
  <scroll-view class="chat-history" scroll-y :scroll-into-view="scrollTarget" :scroll-with-animation="false">
    <button v-if="hasMore" class="chat-older" @tap="older">加载更早消息</button><view v-if="loading&&!messages.length" class="chat-empty">正在读取对话…</view><view v-else-if="!messages.length&&!error" class="chat-empty">从一声问候开始吧</view>
    <view v-for="m in messages" :id="'message-'+m.id" :key="m.id" class="chat-message" :class="{'chat-message--mine':m.mine}"><view class="chat-avatar">{{ m.senderName.slice(-2) }}</view><view class="chat-message-body"><text class="chat-byline">{{ m.senderName }} · {{ time(m.createdAt) }}</text><view class="chat-bubble" :class="{'chat-bubble--media':m.kind==='image'||m.kind==='sticker'}"><text v-if="m.kind==='text'" selectable>{{ m.text }}</text><template v-else-if="m.kind==='sticker'"><image v-if="m.sticker?.url" :src="asset(m.sticker.url)" mode="aspectFit" class="chat-sticker-image"/><text v-else>表情已下架</text></template><template v-else-if="m.attachment"><image v-if="m.kind==='image'&&previews[m.attachment.id]" :src="previews[m.attachment.id]" class="chat-photo" mode="widthFix" @tap="preview(m.attachment)" @error="expirePreview(m.attachment.id)"/><button v-else class="chat-file" @tap="download(m.attachment)"><text class="chat-file-icon">{{ m.kind==='image'?'图':'文' }}</text><view><text>{{ m.attachment.name }}</text><text>{{ size(m.attachment.size) }} · 点击{{ m.kind==='image'?'查看':'下载' }}</text></view><text>↓</text></button></template></view></view></view><view id="chat-bottom" class="chat-bottom"></view>
  </scroll-view>
  <view v-if="conversation?.status==='paused'" class="chat-error">此会话已被管理员停用，可查看历史记录，暂不能发送新消息。</view>
  <view v-if="conversation?.status==='dissolved'" class="chat-error">此自建群已由群主解散。历史消息保留，但所有成员都不能继续发言或管理群聊。</view>
  <view v-if="readOnly&&upload" class="chat-upload"><view><text>{{ upload.name }}</text><text>会话已停止接收新消息，上传已暂停，可取消未发送附件。</text></view><button @tap="cancelUpload">取消附件</button></view>
  <view v-if="conversation&&!readOnly" class="chat-composer">
    <view v-if="upload" class="chat-upload"><view><text>{{ upload.name }}</text><text>{{ upload.percent }}% · {{ uploading?'上传中':upload.ready?'上传完成，等待发送':'已暂停，重新选择原文件可续传' }}</text></view><button v-if="uploading" @tap="pauseUpload">暂停</button><button v-else-if="upload.ready" :disabled="sending" @tap="sendAttachment">发送</button><button v-else @tap="choose(false,true)">续传</button><button :disabled="sending" @tap="cancelUpload">取消</button></view>
    <view v-if="emojiOpen" class="chat-emoji-panel"><view class="chat-emoji-tabs"><button :class="{active:stickerCategory==='emoji'}" @tap="stickerCategory='emoji'">表情</button><button v-for="c in categories" :key="c" :class="{active:stickerCategory===c}" @tap="stickerCategory=c">{{ c }}</button></view><view v-if="stickerCategory==='emoji'" class="chat-emoji-grid"><button v-for="e in emojis" :key="e" @tap="draft+=e">{{ e }}</button></view><view v-else class="chat-sticker-grid"><button v-for="s in stickers.filter(s=>s.category===stickerCategory)" :key="s.id" :disabled="sending" @tap="send('sticker',s.id)"><image :src="asset(s.url)" mode="aspectFit"/><text>{{ s.name }}</text></button></view><text v-if="!stickers.length" class="chat-subtitle">管理员上架表情包后可在这里使用</text></view>
    <view class="chat-input-row"><textarea v-model="draft" :maxlength="4000" :disabled="sending" auto-height :show-confirm-bar="false" placeholder="输入消息…"/><button :disabled="sending||!draft.trim()||!conversation" :loading="sending" @tap="send('text')">发送</button></view>
    <view class="chat-tools"><button @tap="openEmoji">☺ 表情</button><button :disabled="uploading||!!upload" @tap="choose(true)">▧ 图片</button><button :disabled="uploading||!!upload" @tap="choose(false)">＋ 文件</button><text>单文件 ≤ 5GB</text></view>
  </view>
  <view v-if="membersOpen&&conversation" class="chat-member-overlay" @tap.self="membersOpen=false"><view class="chat-member-panel">
    <view class="chat-panel-title"><text>群成员与管理</text><button @tap="membersOpen=false">关闭</button></view>
    <text v-if="error" class="chat-error" role="alert">{{ error }}</text>
    <view v-if="conversation.schoolGroup" class="chat-school-note"><text>{{ schoolLabel(conversation.schoolGroup) }} · 学籍自动关联</text><text>这是系统固定群，成员按已核验学籍自动关联，不支持自行退出或解散。群主由后台指定。</text></view>
    <view v-if="groupPermissions.rename&&!readOnly" class="chat-rename"><input v-model="newTitle" maxlength="60" placeholder="修改群名"/><button :disabled="managing||!newTitle.trim()" @tap="manage({title:newTitle})">保存群名</button></view>
    <template v-if="canAddMembers"><view class="chat-rename"><input v-model="peopleQuery" placeholder="搜索实名用户" @confirm="searchPeople"/><button @tap="searchPeople">搜索</button></view><view v-for="p in people" :key="p.id" class="chat-member"><text>{{ p.name }} · {{ p.department }}</text><button :disabled="managing" @tap="manage({addIds:[p.id]})">加入群聊</button></view></template>
    <scroll-view scroll-y class="chat-members"><view v-for="p in conversation.members" :key="p.id" class="chat-member"><view class="chat-member-info"><text>{{ p.name }}</text><text class="chat-role">{{ memberRole(p) }}</text><text class="chat-subtitle">{{ p.department }}</text></view><view class="chat-member-actions"><button v-if="groupPermissions.manageAdmins&&!readOnly&&p.role!=='owner'&&p.id!==selfId" :disabled="managing" @tap="changeAdmin(p)">{{ p.role==='admin'?'撤销管理员':'设为管理员' }}</button><button v-if="canRemove(p)" :disabled="managing" @tap="remove(p)">移出</button></view></view></scroll-view>
    <text class="chat-subtitle">新加入的成员只能看到加入后的消息和附件。</text><text v-if="!fixedGroup&&isOwner&&conversation.status!=='dissolved'" class="chat-subtitle">你是自建群群主，可解散群聊；如需保留群聊后离开，请先联系后台转交群主。</text>
    <button v-if="canLeave" class="chat-leave" :disabled="managing" @tap="leave">退出群聊</button>
    <button v-if="canDissolve" class="chat-leave chat-dissolve" :disabled="managing" @tap="dissolve">解散自建群</button>
  </view></view>
</view></template>
<script>
import { chatApi,chatUrl,chatFileLink,downloadChatFile,pickChatFile,uploadChatFile,messageId,fileSize } from '../services/chat'
import { request } from '../services/http'
import { getAccessToken } from '../utils/store'
import { openPage } from '../utils/nav'
import { conversationTitle, isFixedGroup, canLeaveGroup, canDissolveGroup } from '../utils/chatGroups'
export default{
  props:{conversationId:{type:String,default:''},active:{type:Boolean,default:true},embedded:{type:Boolean,default:false}},
  emits:['back'],
  watch:{conversationId(value){this.stop();this.id=value;this.resetSession(getAccessToken());if(this.active)this.activate()},active(value){if(value)this.activate();else this.stop()}},
  mounted(){this.id=this.conversationId||this.id;if(this.active)this.activate()},
  beforeUnmount(){this.stop()},
  data:()=>({id:'',conversation:null,messages:[],draft:'',error:'',loading:false,sending:false,hasMore:false,scrollTarget:'',generation:0,timer:null,sessionToken:'',meId:'',previews:{},emojiOpen:false,stickers:[],stickerCategory:'emoji',emojis:['😀','😄','😊','🥰','😍','🤔','😎','😭','😂','🥳','👍','👏','🙏','❤️','🌹','🎉','☕','🎓','💪','🤝'],membersOpen:false,newTitle:'',peopleQuery:'',people:[],managing:false,upload:null,uploading:false,uploadAbort:null,pendingMessage:null,olderLoading:false,readEpoch:0}),
  computed:{fixedGroup(){return isFixedGroup(this.conversation)},canLeave(){return canLeaveGroup(this.conversation,this.selfId)},canDissolve(){return canDissolveGroup(this.conversation,this.selfId)},readOnly(){return ['paused','dissolved'].includes(this.conversation?.status)},categories(){return [...new Set(this.stickers.map(s=>s.category))]},isOwner(){return !!this.selfId&&this.conversation?.ownerId===this.selfId},selfId(){return this.meId||''},groupPermissions(){return this.conversation?.permissions||{}},canAddMembers(){return !this.readOnly&&!this.conversation?.schoolGroup&&this.groupPermissions.addMembers!==false&&this.groupPermissions.manageMembers===true}},
  methods:{activate(){this.stop();if(this.sessionToken!==getAccessToken())this.resetSession(getAccessToken());if(!this.id||!this.active)return;this.refresh(true);this.timer=setInterval(()=>this.refresh(),5000)},conversationTitle,size:fileSize,asset:chatUrl,back(){if(this.embedded){this.$emit('back');return}openPage('/pages/conversations/index')},time(v){return new Date(v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})},valid(g,t){return g===this.generation&&t===getAccessToken()},stop(){this.generation++;this.readEpoch++;this.olderLoading=false;clearInterval(this.timer);this.pauseUpload();this.previews={};this.loading=false;this.sending=false;this.managing=false},storageKey(){return 'hufe_chat_upload_'+this.id},restoreUpload(){const old=uni.getStorageSync(this.storageKey());if(old&&old.ownerId===this.meId)this.upload=old},persistUpload(){if(this.upload)uni.setStorageSync(this.storageKey(),{...this.upload,ownerId:this.meId});else uni.removeStorageSync(this.storageKey())},scroll(){this.scrollTarget='';this.$nextTick(()=>{this.scrollTarget='chat-bottom'})},
    begin(){const token=getAccessToken();if(!token||token!==this.sessionToken){this.generation++;this.resetSession(token);this.error='登录账号已变化，请重新进入对话';return null}return {token,g:this.generation}},
    async openEmoji(){const s=this.begin();if(!s)return;this.emojiOpen=!this.emojiOpen;if(!this.emojiOpen)return;try{const r=await chatApi('/stickers',{token:s.token});if(this.valid(s.g,s.token))this.stickers=r.items}catch(e){if(this.valid(s.g,s.token))this.error=e.message}},
    resetSession(token){this.pauseUpload();this.sessionToken=token;this.messages=[];this.conversation=null;this.meId='';this.previews={};this.upload=null;this.draft='';this.pendingMessage=null;this.readEpoch++;this.olderLoading=false;this.people=[];this.membersOpen=false;this.emojiOpen=false;this.loading=false;this.sending=false;this.managing=false},
    async refresh(initial=false){const token=getAccessToken();if(token!==this.sessionToken){this.generation++;this.resetSession(token);initial=true}if(this.loading)return;const g=this.generation;if(!token){this.error='请先登录再进入对话';return}this.loading=true;try{if(initial||!this.conversation){const me=await request({path:'/api/v1/me',token});const c=await chatApi('/conversations/'+this.id,{token});if(!this.valid(g,token))return;this.conversation=c;this.newTitle=c.title;if(me)this.meId=me.id;this.restoreUpload();const s=await chatApi('/stickers',{token});if(!this.valid(g,token))return;this.stickers=s.items}const after=initial?0:this.messages.at(-1)?.seq||0;const params=new URLSearchParams();if(after)params.set('after',String(after));params.set('revision',String(this.conversation?.moderationRevision||0));const r=await chatApi('/conversations/'+this.id+'/messages?'+params,{token});if(!this.valid(g,token))return;if((r.groupRevision!==undefined&&Number(r.groupRevision)<Number(this.conversation?.groupRevision||0))||(this.conversation?.status==='dissolved'&&r.status!=='dissolved'))return;if(this.conversation?.type==='group'&&Number(r.groupRevision||0)>Number(this.conversation.groupRevision||0)){await this.refreshGroup();if(!this.valid(g,token)||!this.conversation)return}if(Number(r.revision||0)<Number(this.conversation?.moderationRevision||0))return;if(r.reset){this.previews={};initial=true}if(initial)this.readEpoch++;if(this.conversation){this.conversation.status=r.status||'active';this.conversation.moderationRevision=r.revision||0;if(['paused','dissolved'].includes(r.status)){this.pauseUpload();this.emojiOpen=false;this.people=[]}}this.messages=initial?r.items:[...this.messages,...r.items.filter(x=>!this.messages.some(y=>y.id===x.id))];if(initial){this.hasMore=r.hasMore;this.error='';}if(r.items.length){this.scroll();await chatApi('/conversations/'+this.id+'/read',{method:'POST',token,data:{seq:this.messages.at(-1).seq}});this.loadPreviews(r.items,g,token)}}catch(e){if(this.valid(g,token)){this.error=e.message;if([401,403].includes(e.statusCode)){this.messages=[];this.conversation=null;this.previews={};this.membersOpen=false}}}finally{if(this.valid(g,token))this.loading=false}},
    async older(){const token=getAccessToken(),g=this.generation,epoch=this.readEpoch;if(!this.messages.length||this.olderLoading)return;this.olderLoading=true;try{const r=await chatApi('/conversations/'+this.id+'/messages?revision='+(this.conversation?.moderationRevision||0)+'&before='+this.messages[0].seq,{token});if(!this.valid(g,token)||epoch!==this.readEpoch||Number(r.revision||0)<Number(this.conversation?.moderationRevision||0)||(r.groupRevision!==undefined&&Number(r.groupRevision)<Number(this.conversation?.groupRevision||0))||(this.conversation?.status==='dissolved'&&r.status!=='dissolved'))return;if(r.reset){this.readEpoch++;this.previews={};this.messages=[]}if(this.conversation){this.conversation.moderationRevision=r.revision||0;this.conversation.status=r.status||'active'}this.messages=[...r.items.filter(m=>!this.messages.some(old=>old.id===m.id)),...this.messages];this.hasMore=r.hasMore;this.loadPreviews(r.items,g,token)}catch(e){if(this.valid(g,token))this.error=e.message}finally{if(this.valid(g,token))this.olderLoading=false}},
    async loadPreviews(rows,g,t){for(const m of rows.filter(m=>m.kind==='image'&&m.attachment&&m.attachment.size<=20*1024*1024)){if(!this.valid(g,t))return;try{const url=await chatFileLink(m.attachment.id,t);if(!this.valid(g,t)||!this.messages.some(row=>row.attachment?.id===m.attachment.id))return;this.previews={...this.previews,[m.attachment.id]:url}}catch{}}},expirePreview(id){const copy={...this.previews};delete copy[id];this.previews=copy},
    async preview(a){const s=this.begin();if(!s)return;try{const url=await chatFileLink(a.id,s.token);if(this.valid(s.g,s.token))uni.previewImage({urls:[url]})}catch(e){if(this.valid(s.g,s.token))this.error=e.message}},
    async download(a){const s=this.begin();if(!s)return;try{const url=await chatFileLink(a.id,s.token);if(this.valid(s.g,s.token))downloadChatFile(url)}catch(e){if(this.valid(s.g,s.token))this.error=e.message}},
    async send(kind,stickerId='',attachmentId=''){const s=this.begin();if(!s||this.sending)return;if(this.readOnly){this.error=this.conversation.status==='dissolved'?'群聊已解散，不能发送新消息或上传附件':'此会话已被管理员停用';return;}const {token,g}=s;const payload={kind,...(kind==='text'?{text:this.draft}:{}),...(stickerId?{stickerId}:{}),...(attachmentId?{attachmentId}:{})};const signature=JSON.stringify(payload);if(!this.pendingMessage||this.pendingMessage.signature!==signature)this.pendingMessage={signature,id:messageId()};this.sending=true;this.error='';try{await chatApi('/conversations/'+this.id+'/messages',{method:'POST',token,data:{...payload,clientMessageId:this.pendingMessage.id}});if(!this.valid(g,token))return;this.pendingMessage=null;if(kind==='text')this.draft='';if(attachmentId){this.upload=null;this.persistUpload()}this.emojiOpen=false;await this.refresh()}catch(e){if(this.valid(g,token))this.error=e.message}finally{if(this.valid(g,token))this.sending=false}},
    async choose(images=false,resume=false){const s=this.begin();if(!s||this.uploading)return;if(this.readOnly){this.error=this.conversation.status==='dissolved'?'群聊已解散，不能发送新消息或上传附件':'此会话已被管理员停用';return;}const {token,g}=s;this.error='';try{const file=await pickChatFile(images);if(!file||!this.valid(g,token)||this.readOnly)return;this.uploadAbort=new AbortController();this.uploading=true;const result=await uploadChatFile(file,this.id,{existingId:resume?this.upload?.id:'',signal:this.uploadAbort.signal,onProgress:p=>{if(this.valid(g,token)){this.upload={...p,ready:false};this.persistUpload()}}});if(!this.valid(g,token))return;if(result.status==='bound'){this.upload=null;this.persistUpload();await this.refresh(true);return}this.upload={...this.upload,ready:true,mimeType:result.mimeType};this.persistUpload();await this.sendAttachment()}catch(e){if(this.valid(g,token))this.error=e.message}finally{if(this.valid(g,token))this.uploading=false}},
    pauseUpload(){this.uploadAbort?.abort();this.uploading=false},
    async cancelUpload(){const s=this.begin();if(!s)return;this.pauseUpload();const current=this.upload;if(!current)return;try{const task=await chatApi('/uploads/'+current.id,{token:s.token});if(task.status!=='bound')await chatApi('/uploads/'+current.id,{method:'DELETE',token:s.token});if(!this.valid(s.g,s.token))return;this.upload=null;this.persistUpload();await this.refresh()}catch(e){if(this.valid(s.g,s.token)){if([404,410].includes(e.statusCode)){this.upload=null;this.persistUpload()}else this.error=e.message}}},
    async sendAttachment(){const s=this.begin();if(!s||!this.upload?.ready)return;try{const task=await chatApi('/uploads/'+this.upload.id,{token:s.token});if(!this.valid(s.g,s.token))return;if(task.status==='bound'){this.upload=null;this.persistUpload();await this.refresh(true);return}return this.send(task.mimeType?.startsWith('image/')?'image':'file','',task.id)}catch(e){if(this.valid(s.g,s.token))this.error=e.message}},
    schoolLabel(group){return ({college:'学院群',department:'学院群',major:'专业群',class:'班级群'})[group?.kind]||'学籍群'},
    memberRole(p){return ({owner:'群主',admin:'管理员',member:'群成员'})[p.role]||'群成员'},
    canRemove(p){return !!p?.id&&!this.fixedGroup&&!this.readOnly&&this.groupPermissions.removeMembers!==false&&this.groupPermissions.manageMembers===true&&p.id!==this.selfId&&p.id!==this.conversation?.ownerId&&p.role!=='owner'&&(this.isOwner||p.role!=='admin')},
    applyGroup(result){if(!result||Number(result.groupRevision||0)<Number(this.conversation?.groupRevision||0))return;const previous=this.conversation;this.conversation=result;if(result.status==='dissolved'){this.pauseUpload();this.emojiOpen=false;this.people=[]}if(!this.newTitle||this.newTitle===previous?.title)this.newTitle=result.title;if(!result.permissions?.manageMembers||result.schoolGroup)this.people=[]},
    async refreshGroup(){const s=this.begin();if(!s)return;try{const c=await chatApi('/conversations/'+this.id,{token:s.token});if(this.valid(s.g,s.token))this.applyGroup(c)}catch(e){if(this.valid(s.g,s.token)){this.error=e.message;if([401,403].includes(e.statusCode)){this.conversation=null;this.messages=[];this.previews={};this.membersOpen=false}}}},
    async toggleMembers(){if(!this.begin())return;this.membersOpen=!this.membersOpen;if(this.membersOpen)await this.refreshGroup()},
    async searchPeople(){const s=this.begin(),q=this.peopleQuery;if(!s||!this.canAddMembers)return;try{const r=await chatApi('/people?query='+encodeURIComponent(q),{token:s.token});if(!this.valid(s.g,s.token)||q!==this.peopleQuery||!this.conversation||!this.canAddMembers)return;this.people=r.items.filter(p=>!this.conversation.members.some(m=>m.id===p.id))}catch(e){if(this.valid(s.g,s.token))this.error=e.message}},
    async manage(body){const s=this.begin();if(!s||this.managing)return;const permissions=this.conversation?.permissions||{};if(this.readOnly||body.title!==undefined&&!permissions.rename||body.addIds&&!this.canAddMembers||body.removeId&&!this.canRemove(this.conversation?.members.find(p=>p.id===body.removeId)||{})||body.adminId&&!permissions.manageAdmins){this.error='当前没有执行此群管理操作的权限';return}this.managing=true;this.error='';try{const result=await chatApi('/conversations/'+this.id,{method:'PATCH',data:{revision:this.conversation?.groupRevision||0,...body},token:s.token});if(!this.valid(s.g,s.token))return;this.applyGroup(result);this.people=[];this.newTitle=this.conversation?.title||''}catch(e){if(this.valid(s.g,s.token)){this.error=e.message;if(e.statusCode===409)await this.refreshGroup()}}finally{if(this.valid(s.g,s.token))this.managing=false}},
    changeAdmin(p){const s=this.begin();if(!s||!this.groupPermissions.manageAdmins||p.role==='owner'||p.id===this.selfId||this.readOnly)return;const role=p.role==='admin'?'member':'admin',revision=this.conversation.groupRevision||0;uni.showModal({title:role==='admin'?'设置群管理员':'撤销群管理员',content:role==='admin'?'设置'+p.name+'为群管理员，可协助管理群成员。':'撤销'+p.name+'的管理员权限，保留群成员身份。',success:r=>{if(r.confirm&&this.valid(s.g,s.token))this.manage({adminId:p.id,role,revision})}})},
    remove(p){const s=this.begin();if(!s||!this.canRemove(p))return;const revision=this.conversation.groupRevision||0;uni.showModal({title:'移出群聊',content:'确定将'+p.name+'移出群聊？',success:r=>{if(r.confirm&&this.valid(s.g,s.token))this.manage({removeId:p.id,revision})}})},
    leave(){const s=this.begin();if(!s||!this.canLeave||this.managing)return;const cid=this.id;uni.showModal({title:'退出自建群',content:'退出“'+conversationTitle(this.conversation)+'”后不能再查看本群消息和附件。其他成员不受影响。',confirmText:'确认退出',success:async r=>{if(!r.confirm||!this.valid(s.g,s.token)||cid!==this.id||!this.canLeave||this.managing)return;this.managing=true;try{await chatApi('/conversations/'+cid+'/leave',{method:'POST',token:s.token});if(this.valid(s.g,s.token)){this.pauseUpload();this.membersOpen=false;this.back()}}catch(e){if(this.valid(s.g,s.token)){this.error=e.message;await this.refreshGroup()}}finally{if(this.valid(s.g,s.token))this.managing=false}}})},
    dissolve(){const s=this.begin();if(!s||!this.canDissolve||this.managing)return;const cid=this.id,revision=this.conversation.groupRevision||0;uni.showModal({title:'解散自建群？',content:'解散“'+conversationTitle(this.conversation)+'”后，全部成员将无法继续发送消息、上传附件或管理群聊。此操作不可恢复，历史记录仍保留供查看。',confirmText:'确认解散',confirmColor:'#a33d32',success:async r=>{if(!r.confirm||!this.valid(s.g,s.token)||cid!==this.id||!this.canDissolve||this.managing)return;this.managing=true;this.error='';try{const result=await chatApi('/conversations/'+cid+'/dissolve',{method:'POST',token:s.token,data:{revision}});if(!this.valid(s.g,s.token)||cid!==this.id)return;this.applyGroup(result.conversation);this.pauseUpload();this.emojiOpen=false;this.people=[];this.membersOpen=false;uni.showToast({title:'群聊已解散',icon:'none'})}catch(e){if(this.valid(s.g,s.token)){this.error=e.message;if([401,403,409,410].includes(e.statusCode))await this.refreshGroup();if(e.statusCode===409&&this.valid(s.g,s.token))this.error='群信息已更新，请核对最新信息后重新确认解散。'}}finally{if(this.valid(s.g,s.token))this.managing=false}}})}
  }
}
</script>
